WITH hta_ativos AS (  SELECT DISTINCT co_fat_cidadao_pec  FROM stg_atendimento  WHERE atend_ind_classificacao LIKE '%HIPERTENS%'    AND atend_ind_classificacao NOT LIKE '%RESOLVID%'    AND familia_cbo IN (SELECT familia FROM cbo_por_pratica WHERE pratica = 'consulta')), resolvidos_por_cid AS (  SELECT co_fat_cidadao_pec, MAX(dt_registro) dt_ultima_resolucao  FROM stg_atendimento  WHERE atend_ind_classificacao LIKE '%RESOLVID%'  GROUP BY co_fat_cidadao_pec), reativados AS (  SELECT r.co_fat_cidadao_pec  FROM resolvidos_por_cid r  WHERE EXISTS (    SELECT 1 FROM stg_atendimento a    WHERE a.co_fat_cidadao_pec = r.co_fat_cidadao_pec      AND a.atend_ind_classificacao LIKE '%HIPERTENS%'      AND a.atend_ind_classificacao NOT LIKE '%RESOLVID%'      AND a.familia_cbo IN (SELECT familia FROM cbo_por_pratica WHERE pratica = 'consulta')      AND a.dt_registro > r.dt_ultima_resolucao  )), falecidos AS (  SELECT co_fat_cidadao_pec  FROM stg_cidadao  WHERE st_faleceu = 1)CREATE TABLE int_coorte_hipertensao ASSELECT DISTINCT c.co_fat_cidadao_pecFROM hta_ativos hJOIN stg_cidadao c ON h.co_fat_cidadao_pec = c.co_fat_cidadao_pecWHERE NOT EXISTS (SELECT 1 FROM falecidos f WHERE f.co_fat_cidadao_pec = c.co_fat_cidadao_pec)  AND (    NOT EXISTS (SELECT 1 FROM resolvidos_por_cid r WHERE r.co_fat_cidadao_pec = c.co_fat_cidadao_pec)    OR EXISTS (SELECT 1 FROM reativados rt WHERE rt.co_fat_cidadao_pec = c.co_fat_cidadao_pec)  );CREATE TABLE reativados ASSELECT r.co_fat_cidadao_pecFROM resolvidos_por_cid rWHERE EXISTS (  SELECT 1 FROM stg_atendimento a  WHERE a.co_fat_cidadao_pec = r.co_fat_cidadao_pec    AND a.atend_ind_classificacao LIKE '%HIPERTENS%'    AND a.atend_ind_classificacao NOT LIKE '%RESOLVID%'    AND a.familia_cbo IN (SELECT familia FROM cbo_por_pratica WHERE pratica = 'consulta')    AND a.dt_registro > r.dt_ultima_resolucao);WITH ref AS (SELECT data_referencia FROM param LIMIT 1), w6 AS (SELECT DATE(ref.data_referencia, '-6 months') dt FROM ref, param)CREATE TABLE int_ultima_consulta ASSELECT DISTINCT ON (a.co_fat_cidadao_pec)  a.co_fat_cidadao_pec,  MAX(a.dt_registro) OVER (PARTITION BY a.co_fat_cidadao_pec) dt_ultimaFROM stg_atendimento aJOIN cbo_por_pratica cbop ON a.familia_cbo = cbop.familia AND cbop.pratica = 'consulta'ORDER BY a.co_fat_cidadao_pec, a.dt_registro DESC;CREATE TABLE int_ultima_afericao_pa ASSELECT DISTINCT ON (p.co_fat_cidadao_pec)  p.co_fat_cidadao_pec,  MAX(p.dt_registro) OVER (PARTITION BY p.co_fat_cidadao_pec) dt_ultima,  p.pa_sistolica,  p.pa_diastolicaFROM stg_procedimentos pJOIN cbo_por_pratica cbop ON p.familia_cbo = cbop.familia AND cbop.pratica = 'pa'WHERE p.co_proced = '0301100039'  -- AFERIÇÃO DE PRESSÃO ARTERIAL  AND p.pa_sistolica IS NOT NULL  AND p.pa_diastolica IS NOT NULLORDER BY p.co_fat_cidadao_pec, p.dt_registro DESC;CREATE TABLE int_ultimo_peso_altura ASSELECT  pa_by_day.co_fat_cidadao_pec,  pa_by_day.dt_registro dt_ultimaFROM (  SELECT DISTINCT ON (p.co_fat_cidadao_pec, p.dt_registro)    p.co_fat_cidadao_pec,    p.dt_registro,    ROW_NUMBER() OVER (PARTITION BY p.co_fat_cidadao_pec ORDER BY p.dt_registro DESC) rn  FROM stg_procedimentos p  JOIN cbo_por_pratica cbop ON p.familia_cbo = cbop.familia AND cbop.pratica = 'peso_altura'  WHERE p.co_proced = '0101040024'  -- MEDIÇÃO PESO E ALTURA    AND p.peso IS NOT NULL    AND p.altura IS NOT NULL) pa_by_dayWHERE rn = 1;CREATE INDEX idx_int_coorte_cid ON int_coorte_hipertensao(co_fat_cidadao_pec);CREATE INDEX idx_int_cons_cid ON int_ultima_consulta(co_fat_cidadao_pec);CREATE INDEX idx_int_pa_cid ON int_ultima_afericao_pa(co_fat_cidadao_pec);CREATE INDEX idx_int_pz_cid ON int_ultimo_peso_altura(co_fat_cidadao_pec);